// The store slice the module RESOLVER reads — `algorithmImpls` is what `resolveGraphSource` matches a
// `provides` against, and it vendors that record's `code`.
//
// THE BUG THIS EXISTS FOR. `hydrateAlgorithms` used to call `loadGraph`, the same read the Algorithms
// page polls. When that read was projected down to an INDEX — no bodies, so the page's 5-second poll
// stopped shipping 50.76 MB — the resolver's feed lost its bodies with it, and every record-provided
// `@/…` import in the app resolved to null. The Algorithms page is itself built from those records, so
// it did not lose rows: it stopped loading. Nothing caught it, because both halves were individually
// correct and no test asserted the contract BETWEEN them.
import { describe, it, expect, vi, beforeEach } from "vitest";

const loadModules = vi.fn();
const loadGraph = vi.fn();
vi.mock("@/features/algorithms/lib/graphBridge", () => ({
  loadModules: () => loadModules(),
  loadGraph: () => loadGraph(),
}));

import { createAlgorithmsSlice } from "@/features/algorithms/store";

/** Drive the slice with a minimal zustand-shaped `set`. */
function slice() {
  let state: Record<string, unknown> = {};
  const set = (patch: Record<string, unknown>) => {
    state = { ...state, ...patch };
  };
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const s = createAlgorithmsSlice(set as any, (() => state) as any, {} as any);
  return { s, read: () => state };
}

describe("the algorithms slice feeds the module resolver", () => {
  beforeEach(() => {
    loadModules.mockReset();
    loadGraph.mockReset();
    loadModules.mockResolvedValue({
      implementations: [{ id: "m.ts", provides: "@/features/x/m", code: "export const m = 1;" }],
    });
    loadGraph.mockResolvedValue({ implementations: [{ id: "m.ts", provides: "@/features/x/m" }] });
  });

  it("reads the RESOLVER feed, never the page's index", async () => {
    const { s } = slice();
    await s.hydrateAlgorithms();
    expect(loadModules, "the resolver needs bodies; the page index has none").toHaveBeenCalled();
    expect(loadGraph, "reading the page's index here is the bug that stopped the app resolving").not.toHaveBeenCalled();
  });

  it("stores records that actually carry their source", async () => {
    // The property that matters downstream, asserted directly rather than via the call: whatever lands
    // in `algorithmImpls` must be able to answer `provides` -> `code`, because that IS resolution.
    const { s, read } = slice();
    await s.hydrateAlgorithms();
    const impls = read().algorithmImpls as { provides?: string; code?: string }[];
    expect(impls).toHaveLength(1);
    expect(impls[0].provides).toBe("@/features/x/m");
    expect(impls[0].code, "a record with no `code` resolves to null and the import fails").toBeTruthy();
  });

  it("keeps the previous set when the read is unavailable, rather than emptying it", async () => {
    // A degraded environment (web shell, tests, an old `bsc`) must resolve nothing NEW — not un-resolve
    // everything it already had.
    loadModules.mockResolvedValue(null);
    const { s, read } = slice();
    await s.hydrateAlgorithms();
    expect(read().algorithmImpls).toBeUndefined();
  });
});
